auto func (auto value){  
    int count = 0;  
    for (int i = 0; i < value.size(); i++){  
        if (isalpha(value[i])){  
            count++;  
        }  
    }  
    return count;  
}

auto func (auto value){  
    int count = 0;  
    for (int i = 0; i < value.size(); i++) {  
        count += 1;  
    }  
    return count;  
}

auto func (auto value){  
    int count = 0;  
    for (char c : value) {  
        if (islower(c)) {  
            count++;  
        }  
    }  
    return count;  
}
